import heapq

def match(orders):
    trades = []
    # order books: price -> list of [id, qty, seq] (list acting as queue)
    buy_book = {}  # price -> deque-like list
    sell_book = {}
    buy_heap = []  # (-price, ) for max-heap of buy prices
    sell_heap = []  # (price,) for min-heap of sell prices

    order_info = {}  # id -> dict with side, price, remaining qty, seq, active(bool), in book
    seq_counter = 0

    def add_to_book(side, oid, price, qty, seq):
        entry = [oid, qty, seq]
        if side == 'buy':
            if price not in buy_book:
                buy_book[price] = []
                heapq.heappush(buy_heap, -price)
            buy_book[price].append(entry)
        else:
            if price not in sell_book:
                sell_book[price] = []
                heapq.heappush(sell_heap, price)
            sell_book[price].append(entry)

    def clean_buy_heap():
        while buy_heap and (-buy_heap[0] not in buy_book or not buy_book[-buy_heap[0]]):
            p = -heapq.heappop(buy_heap)
            if p in buy_book and not buy_book[p]:
                del buy_book[p]

    def clean_sell_heap():
        while sell_heap and (sell_heap[0] not in sell_book or not sell_book[sell_heap[0]]):
            p = heapq.heappop(sell_heap)
            if p in sell_book and not sell_book[p]:
                del sell_book[p]

    def best_buy_price():
        clean_buy_heap()
        if buy_heap:
            return -buy_heap[0]
        return None

    def best_sell_price():
        clean_sell_heap()
        if sell_heap:
            return sell_heap[0]
        return None

    def match_incoming(side, oid, price, qty, is_market_or_ioc_price_check):
        # price: for market orders, price param is None meaning any price
        # is_market_or_ioc_price_check: function(resting_price) -> bool whether can match
        remaining = qty
        if side == 'buy':
            while remaining > 0:
                bp = best_sell_price()
                if bp is None:
                    break
                if not is_market_or_ioc_price_check(bp):
                    break
                queue = sell_book[bp]
                while remaining > 0 and queue:
                    entry = queue[0]
                    resting_id, resting_qty, resting_seq = entry
                    trade_qty = min(remaining, resting_qty)
                    trades.append([oid, resting_id, bp, trade_qty])
                    remaining -= trade_qty
                    entry[1] -= trade_qty
                    if entry[1] == 0:
                        queue.pop(0)
                        if resting_id in order_info:
                            order_info[resting_id]['active'] = False
                    if remaining == 0:
                        break
                if not queue:
                    del sell_book[bp]
                    clean_sell_heap()
        else:
            while remaining > 0:
                bp = best_buy_price()
                if bp is None:
                    break
                if not is_market_or_ioc_price_check(bp):
                    break
                queue = buy_book[bp]
                while remaining > 0 and queue:
                    entry = queue[0]
                    resting_id, resting_qty, resting_seq = entry
                    trade_qty = min(remaining, resting_qty)
                    trades.append([resting_id, oid, bp, trade_qty])
                    remaining -= trade_qty
                    entry[1] -= trade_qty
                    if entry[1] == 0:
                        queue.pop(0)
                        if resting_id in order_info:
                            order_info[resting_id]['active'] = False
                    if remaining == 0:
                        break
                if not queue:
                    del buy_book[bp]
                    clean_buy_heap()
        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in order_info:
                info = order_info[oid]
                if info['active'] and info['in_book']:
                    side = info['side']
                    price = info['price']
                    book = buy_book if side == 'buy' else sell_book
                    if price in book:
                        queue = book[price]
                        for i, entry in enumerate(queue):
                            if entry[0] == oid:
                                queue.pop(i)
                                break
                        if not queue:
                            del book[price]
                    info['active'] = False
            continue

        typ2 = order[0]
        if typ2 == 'limit':
            _, oid, side, price, qty = order
            def check(rp, side=side, price=price):
                if side == 'buy':
                    return rp <= price
                else:
                    return rp >= price
            remaining = match_incoming(side, oid, price, qty, check)
            order_info[oid] = {'side': side, 'price': price, 'active': True, 'in_book': False}
            if remaining > 0:
                seq_counter += 1
                add_to_book(side, oid, price, remaining, seq_counter)
                order_info[oid]['in_book'] = True
            else:
                order_info[oid]['active'] = False
        elif typ2 == 'ioc':
            _, oid, side, price, qty = order
            def check(rp, side=side, price=price):
                if side == 'buy':
                    return rp <= price
                else:
                    return rp >= price
            remaining = match_incoming(side, oid, price, qty, check)
            order_info[oid] = {'side': side, 'price': price, 'active': False, 'in_book': False}
        elif typ2 == 'market':
            _, oid, side, qty = order
            def check(rp):
                return True
            remaining = match_incoming(side, oid, None, qty, check)
            order_info[oid] = {'side': side, 'price': None, 'active': False, 'in_book': False}

    return trades

